import React from 'react';

const tabClasses = (isActive) =>
  `px-4 py-2 rounded-full border-none font-semibold cursor-pointer text-[13px] ${
    isActive ? 'bg-sky-400 text-slate-900' : 'bg-slate-800 text-slate-400'
  }`;

/** Filtro por categoría (solo lectura; la gestión de categorías vive en /admin/categories). */
const CategoryTabs = ({ categories, products, active, onChange }) => (
  <div className="flex gap-2 mb-4 flex-wrap">
    <button onClick={() => onChange('all')} className={tabClasses(active === 'all')}>
      Todas ({products.length})
    </button>
    {categories.map((cat) => (
      <button key={cat.id} onClick={() => onChange(cat.id)} className={tabClasses(active === cat.id)}>
        {cat.icon} {cat.name} ({products.filter((p) => p.category_id === cat.id).length})
      </button>
    ))}
  </div>
);

export default CategoryTabs;
